GRANT EXECUTE ON FUNCTION public.chuyen_xe_cua_tai_xe() TO authenticated;
GRANT EXECUTE ON FUNCTION public.cap_nhat_chuyen_xe_tai_xe(BIGINT, TEXT) TO authenticated;

