REVOKE ALL ON FUNCTION public.quan_ly_kho_don_theo_kho(BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.quan_ly_kho_nhan_vien_theo_kho(BIGINT) FROM PUBLIC;
