-- ============================================================

-- Cho quản lý/nhân viên được gán kho cấp 1 tạo kho cấp 2 trực thuộc.

CREATE OR REPLACE FUNCTION public.thong_tin_quyen_tao_kho_cap_2()
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path = public AS $$
DECLARE v_kho public.kho_hang%ROWTYPE;
BEGIN
    SELECT kh.* INTO v_kho FROM public.nhan_vien nv
    JOIN public.kho_hang kh ON kh.id = nv.kho_hang_id
    WHERE nv.auth_user_id = auth.uid()
      AND nv.vai_tro = 'QUAN_LY_KHO'
      AND nv.trang_thai_duyet = 'DA_DUYET' AND nv.trang_thai = 'HOAT_DONG';
    IF NOT FOUND OR v_kho.cap_kho <> 1 THEN RETURN jsonb_build_object('duoc_phep', FALSE); END IF;
    RETURN jsonb_build_object('duoc_phep', TRUE, 'kho_cap_1_id', v_kho.id,
        'ma_kho', v_kho.ma_kho, 'ten_kho', v_kho.ten_kho);
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_tao_kho_cap_2(
    p_ten_kho TEXT, p_dia_chi TEXT, p_tinh_thanh TEXT,
    p_phuong_xa TEXT, p_so_dien_thoai TEXT DEFAULT NULL
)
RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
    v_kho_cha public.kho_hang%ROWTYPE;
    v_khu_vuc_id BIGINT;
    v_ma_kho TEXT;
    v_id BIGINT;
BEGIN
    SELECT kh.* INTO v_kho_cha FROM public.nhan_vien nv
    JOIN public.kho_hang kh ON kh.id = nv.kho_hang_id
    WHERE nv.auth_user_id = auth.uid()
      AND nv.vai_tro = 'QUAN_LY_KHO'
      AND nv.trang_thai_duyet = 'DA_DUYET' AND nv.trang_thai = 'HOAT_DONG'
    FOR UPDATE OF kh;
    IF NOT FOUND OR v_kho_cha.cap_kho <> 1 THEN
        RAISE EXCEPTION 'Chỉ quản lý kho cấp 1 mới được tạo kho cấp 2';
    END IF;
    IF NULLIF(BTRIM(p_ten_kho),'') IS NULL OR NULLIF(BTRIM(p_dia_chi),'') IS NULL
       OR NULLIF(BTRIM(p_tinh_thanh),'') IS NULL OR NULLIF(BTRIM(p_phuong_xa),'') IS NULL THEN
        RAISE EXCEPTION 'Thông tin kho chưa đầy đủ';
    END IF;

    SELECT kv.id INTO v_khu_vuc_id FROM public.khu_vuc kv
    WHERE LOWER(BTRIM(kv.tinh_thanh)) = LOWER(BTRIM(p_tinh_thanh))
      AND LOWER(BTRIM(COALESCE(kv.phuong_xa,''))) = LOWER(BTRIM(p_phuong_xa))
    ORDER BY kv.id LIMIT 1;
    IF v_khu_vuc_id IS NULL THEN
        INSERT INTO public.khu_vuc(ten_khu_vuc,tinh_thanh,quan_huyen,phuong_xa)
        VALUES(BTRIM(p_phuong_xa)||', '||BTRIM(p_tinh_thanh),BTRIM(p_tinh_thanh),NULL,BTRIM(p_phuong_xa))
        RETURNING id INTO v_khu_vuc_id;
    END IF;

    LOOP
        v_ma_kho := 'K2-'||UPPER(SUBSTRING(REPLACE(gen_random_uuid()::TEXT,'-','') FROM 1 FOR 8));
        EXIT WHEN NOT EXISTS(SELECT 1 FROM public.kho_hang WHERE ma_kho=v_ma_kho);
    END LOOP;
    INSERT INTO public.kho_hang(ma_kho,ten_kho,dia_chi,khu_vuc_id,so_dien_thoai,
        trang_thai,cap_kho,kho_trung_tam_id)
    VALUES(v_ma_kho,BTRIM(p_ten_kho),BTRIM(p_dia_chi),v_khu_vuc_id,
        NULLIF(BTRIM(p_so_dien_thoai),''),'HOAT_DONG',2,v_kho_cha.id)
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$$;

-- Mọi chặng xe tải ra/vào kho cấp 2 bắt buộc đi qua kho cấp 1 cha.
CREATE OR REPLACE FUNCTION public.kiem_tra_chang_kho_cap_2()
RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$
DECLARE
    v_cap_di SMALLINT; v_cha_di BIGINT;
    v_cap_den SMALLINT; v_cha_den BIGINT;
BEGIN
    SELECT cap_kho,kho_trung_tam_id INTO v_cap_di,v_cha_di
    FROM public.kho_hang WHERE id=NEW.kho_di_id;
    SELECT cap_kho,kho_trung_tam_id INTO v_cap_den,v_cha_den
    FROM public.kho_hang WHERE id=NEW.kho_den_id;
    IF v_cap_di=2 AND NEW.kho_den_id<>v_cha_di THEN
        RAISE EXCEPTION 'Kho cấp 2 chỉ được chuyển hàng lên kho cấp 1 trực thuộc';
    END IF;
    IF v_cap_den=2 AND NEW.kho_di_id<>v_cha_den THEN
        RAISE EXCEPTION 'Hàng vào kho cấp 2 phải đi từ kho cấp 1 trực thuộc';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_kiem_tra_chang_kho_cap_2 ON public.chuyen_xe_chang;
CREATE TRIGGER trg_kiem_tra_chang_kho_cap_2
BEFORE INSERT OR UPDATE OF kho_di_id,kho_den_id ON public.chuyen_xe_chang
FOR EACH ROW EXECUTE FUNCTION public.kiem_tra_chang_kho_cap_2();

CREATE OR REPLACE FUNCTION public.nhan_vien_kho_tong_quan()
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path = public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE; v_kho public.kho_hang%ROWTYPE;
BEGIN
    SELECT * INTO v_nv FROM public.nhan_vien WHERE auth_user_id=auth.uid()
      AND vai_tro='NHAN_VIEN_KHO' AND trang_thai_duyet='DA_DUYET' AND trang_thai='HOAT_DONG';
    IF NOT FOUND OR v_nv.kho_hang_id IS NULL THEN RAISE EXCEPTION 'Nhân viên chưa được gán kho'; END IF;
    SELECT * INTO v_kho FROM public.kho_hang WHERE id=v_nv.kho_hang_id;
    RETURN jsonb_build_object(
      'nhan_vien_id',v_nv.id,'ho_ten',v_nv.ho_ten,'so_dien_thoai',v_nv.so_dien_thoai,
      'email',v_nv.email,'kho_id',v_kho.id,'ma_kho',v_kho.ma_kho,'ten_kho',v_kho.ten_kho,
      'dia_chi',v_kho.dia_chi,'cap_kho',v_kho.cap_kho,
      'don_tai_kho',(SELECT COUNT(*) FROM public.don_hang dh WHERE dh.kho_hien_tai_id=v_kho.id),
      'cho_xu_ly',(SELECT COUNT(*) FROM public.don_hang dh WHERE dh.kho_hien_tai_id=v_kho.id
        AND dh.trang_thai IN ('DEN_KHO_TRUNG_CHUYEN','DEN_KHO_DICH')),
      'da_xu_ly_hom_nay',(SELECT COUNT(*) FROM public.nhat_ky_don_hang nk
        WHERE nk.nhan_vien_id=v_nv.id AND nk.thoi_gian::DATE=CURRENT_DATE)
    );
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_kho_don_can_xu_ly()
RETURNS TABLE(id BIGINT,ma_van_don VARCHAR,nguoi_gui_ten VARCHAR,nguoi_nhan_ten VARCHAR,
  nguoi_nhan_dia_chi TEXT,can_nang NUMERIC,trang_thai VARCHAR,ngay_cap_nhat TIMESTAMPTZ)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path = public AS $$
DECLARE v_kho_id BIGINT;
BEGIN
    SELECT nv.kho_hang_id INTO v_kho_id FROM public.nhan_vien nv
    WHERE nv.auth_user_id=auth.uid()
      AND nv.vai_tro='NHAN_VIEN_KHO'
      AND nv.trang_thai_duyet='DA_DUYET'
      AND nv.trang_thai='HOAT_DONG';
    IF v_kho_id IS NULL THEN RAISE EXCEPTION 'Nhân viên chưa được gán kho'; END IF;
    RETURN QUERY SELECT dh.id,dh.ma_van_don::VARCHAR,dh.nguoi_gui_ten::VARCHAR,
      dh.nguoi_nhan_ten::VARCHAR,dh.nguoi_nhan_dia_chi,dh.can_nang,
      dh.trang_thai::VARCHAR,dh.ngay_cap_nhat FROM public.don_hang dh
    WHERE dh.kho_hien_tai_id=v_kho_id
    ORDER BY dh.ngay_cap_nhat DESC LIMIT 200;
END;
$$;

REVOKE ALL ON FUNCTION public.thong_tin_quyen_tao_kho_cap_2() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.nhan_vien_tao_kho_cap_2(TEXT,TEXT,TEXT,TEXT,TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.thong_tin_quyen_tao_kho_cap_2() TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_tao_kho_cap_2(TEXT,TEXT,TEXT,TEXT,TEXT) TO authenticated;
REVOKE ALL ON FUNCTION public.nhan_vien_kho_tong_quan() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.nhan_vien_kho_don_can_xu_ly() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.nhan_vien_kho_tong_quan() TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_kho_don_can_xu_ly() TO authenticated;
NOTIFY pgrst, 'reload schema';


-- ============================================================
-- SOURCE: supabase/last_mile_staff_setup.sql
-- ============================================================

-- Nhân viên chặng đầu/chặng cuối theo địa bàn phường/xã và kho cấp 2.
-- Chạy sau warehouse_level2_creation_setup.sql.

-- Tự chứa hàm chuẩn hóa tiếng Việt, không phụ thuộc extension unaccent hay
-- các file cài đặt đã chạy trước đó.
CREATE OR REPLACE FUNCTION public.bo_dau_lower(p_text TEXT)
RETURNS TEXT LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
  SELECT regexp_replace(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          regexp_replace(
            regexp_replace(
              regexp_replace(lower(COALESCE(p_text,'')),
                '[áàảãạăắằẳẵặâấầẩẫậ]', 'a', 'g'),
              '[éèẻẽẹêếềểễệ]', 'e', 'g'),
            '[íìỉĩị]', 'i', 'g'),
          '[óòỏõọôốồổỗộơớờởỡợ]', 'o', 'g'),
        '[úùủũụưứừửữự]', 'u', 'g'),
      '[ýỳỷỹỵ]', 'y', 'g'),
    'đ', 'd', 'g')
$$;

ALTER TABLE public.nhan_vien
  ADD COLUMN IF NOT EXISTS khu_vuc_id BIGINT REFERENCES public.khu_vuc(id);

CREATE TABLE IF NOT EXISTS public.dia_ban_giao_nhan (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  khu_vuc_id BIGINT NOT NULL REFERENCES public.khu_vuc(id) ON DELETE CASCADE,
  ten_dia_ban VARCHAR(160) NOT NULL,
  loai_dia_ban VARCHAR(20) NOT NULL CHECK (loai_dia_ban IN ('KHU_PHO','AP_THON')),
  trang_thai VARCHAR(20) NOT NULL DEFAULT 'HOAT_DONG'
    CHECK (trang_thai IN ('HOAT_DONG','NGUNG_HOAT_DONG')),
  ngay_tao TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(khu_vuc_id,ten_dia_ban)
);

-- Danh mục mẫu đã xác minh cho Phường An Phú, TP.HCM: 07 khu phố.
-- Giao diện chỉ cho chọn từ danh mục này, không cho nhân viên tự nhập.
INSERT INTO public.dia_ban_giao_nhan(khu_vuc_id,ten_dia_ban,loai_dia_ban)
SELECT kv.id,'Khu phố ' || gs.n,'KHU_PHO'
FROM public.khu_vuc kv
CROSS JOIN generate_series(1,7) AS gs(n)
WHERE public.bo_dau_lower(kv.phuong_xa)='phuong an phu'
  AND public.bo_dau_lower(kv.tinh_thanh) IN (
    'thanh pho ho chi minh','tp ho chi minh','ho chi minh'
  )
ON CONFLICT (khu_vuc_id,ten_dia_ban)
DO UPDATE SET trang_thai='HOAT_DONG';

ALTER TABLE public.nhan_vien
  ADD COLUMN IF NOT EXISTS dia_ban_giao_nhan_id BIGINT
    REFERENCES public.dia_ban_giao_nhan(id);

ALTER TABLE public.nhan_vien DROP CONSTRAINT IF EXISTS chk_nhan_vien_vai_tro;
ALTER TABLE public.nhan_vien ADD CONSTRAINT chk_nhan_vien_vai_tro CHECK (
  vai_tro IN ('ADMIN','QUAN_LY_KHO','NHAN_VIEN_KHO','VAN_CHUYEN','SHIPPER',
              'NHAN_VIEN_LAY_HANG','NHAN_VIEN_GIAO_HANG')
);

ALTER TABLE public.don_hang
  ADD COLUMN IF NOT EXISTS khu_vuc_lay_hang_id BIGINT REFERENCES public.khu_vuc(id),
  ADD COLUMN IF NOT EXISTS khu_vuc_giao_hang_id BIGINT REFERENCES public.khu_vuc(id),
  ADD COLUMN IF NOT EXISTS dia_ban_lay_hang_id BIGINT REFERENCES public.dia_ban_giao_nhan(id),
  ADD COLUMN IF NOT EXISTS dia_ban_giao_hang_id BIGINT REFERENCES public.dia_ban_giao_nhan(id),
  ADD COLUMN IF NOT EXISTS nhan_vien_lay_hang_id BIGINT REFERENCES public.nhan_vien(id),
  ADD COLUMN IF NOT EXISTS nhan_vien_giao_hang_id BIGINT REFERENCES public.nhan_vien(id);

CREATE INDEX IF NOT EXISTS idx_nhan_vien_chang_cuoi
  ON public.nhan_vien(vai_tro,kho_hang_id,khu_vuc_id,dia_ban_giao_nhan_id,trang_thai_duyet,trang_thai);
CREATE INDEX IF NOT EXISTS idx_don_hang_nv_lay
  ON public.don_hang(nhan_vien_lay_hang_id,trang_thai);
CREATE INDEX IF NOT EXISTS idx_don_hang_nv_giao
  ON public.don_hang(nhan_vien_giao_hang_id,trang_thai);

CREATE OR REPLACE FUNCTION public.kiem_tra_dia_ban_nhan_vien_chang_cuoi()
RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public AS $$
DECLARE
  v_kho_cap SMALLINT;
  v_kho_tinh_thanh TEXT;
  v_nhan_vien_tinh_thanh TEXT;
  v_dia_ban_khu_vuc_id BIGINT;
BEGIN
  IF NEW.vai_tro NOT IN ('NHAN_VIEN_LAY_HANG','NHAN_VIEN_GIAO_HANG') THEN
    RETURN NEW;
  END IF;
  IF NEW.kho_hang_id IS NULL OR NEW.khu_vuc_id IS NULL OR NEW.dia_ban_giao_nhan_id IS NULL THEN
    RAISE EXCEPTION 'Nhân viên lấy/giao hàng phải có kho cấp 2 và khu phố/ấp/thôn phụ trách';
  END IF;
  SELECT kh.cap_kho, kv.tinh_thanh
  INTO v_kho_cap, v_kho_tinh_thanh
  FROM public.kho_hang kh
  JOIN public.khu_vuc kv ON kv.id=kh.khu_vuc_id
  WHERE kh.id=NEW.kho_hang_id;
  IF v_kho_cap IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION 'Nhân viên lấy/giao hàng chỉ được gán vào kho cấp 2';
  END IF;
  SELECT kv.tinh_thanh INTO v_nhan_vien_tinh_thanh
  FROM public.khu_vuc kv WHERE kv.id=NEW.khu_vuc_id;
  IF public.bo_dau_lower(v_kho_tinh_thanh)
     IS DISTINCT FROM public.bo_dau_lower(v_nhan_vien_tinh_thanh) THEN
    RAISE EXCEPTION 'Phường/xã phụ trách phải cùng tỉnh/thành với kho cấp 2';
  END IF;
  SELECT db.khu_vuc_id INTO v_dia_ban_khu_vuc_id
  FROM public.dia_ban_giao_nhan db WHERE db.id=NEW.dia_ban_giao_nhan_id;
  IF v_dia_ban_khu_vuc_id IS DISTINCT FROM NEW.khu_vuc_id THEN
    RAISE EXCEPTION 'Khu phố/ấp/thôn không thuộc phường/xã đã chọn';
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_kiem_tra_dia_ban_nhan_vien_chang_cuoi ON public.nhan_vien;
CREATE TRIGGER trg_kiem_tra_dia_ban_nhan_vien_chang_cuoi
BEFORE INSERT OR UPDATE OF vai_tro,kho_hang_id,khu_vuc_id,dia_ban_giao_nhan_id ON public.nhan_vien
FOR EACH ROW EXECUTE FUNCTION public.kiem_tra_dia_ban_nhan_vien_chang_cuoi();

CREATE OR REPLACE FUNCTION public.tim_khu_vuc_theo_dia_chi(p_dia_chi TEXT)
RETURNS BIGINT LANGUAGE sql STABLE SET search_path=public AS $$
  SELECT kv.id FROM public.khu_vuc kv
  WHERE public.bo_dau_lower(p_dia_chi) LIKE '%' || public.bo_dau_lower(kv.phuong_xa) || '%'
    AND public.bo_dau_lower(p_dia_chi) LIKE '%' || public.bo_dau_lower(kv.tinh_thanh) || '%'
  ORDER BY LENGTH(kv.phuong_xa) DESC, kv.id LIMIT 1
$$;

CREATE OR REPLACE FUNCTION public.tim_dia_ban_giao_nhan(
  p_dia_chi TEXT, p_khu_vuc_id BIGINT
) RETURNS BIGINT LANGUAGE sql STABLE SET search_path=public AS $$
  SELECT db.id FROM public.dia_ban_giao_nhan db
  WHERE db.khu_vuc_id=p_khu_vuc_id AND db.trang_thai='HOAT_DONG'
    AND public.bo_dau_lower(p_dia_chi)
        LIKE '%' || public.bo_dau_lower(db.ten_dia_ban) || '%'
  ORDER BY LENGTH(db.ten_dia_ban) DESC, db.id LIMIT 1
$$;

CREATE OR REPLACE FUNCTION public.phan_cong_nhan_vien_chang_cuoi()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF NEW.khu_vuc_lay_hang_id IS NULL THEN
    NEW.khu_vuc_lay_hang_id := public.tim_khu_vuc_theo_dia_chi(NEW.nguoi_gui_dia_chi);
  END IF;
  IF NEW.khu_vuc_giao_hang_id IS NULL THEN
    NEW.khu_vuc_giao_hang_id := public.tim_khu_vuc_theo_dia_chi(NEW.nguoi_nhan_dia_chi);
  END IF;
  NEW.dia_ban_lay_hang_id := public.tim_dia_ban_giao_nhan(
    NEW.nguoi_gui_dia_chi, NEW.khu_vuc_lay_hang_id);
  NEW.dia_ban_giao_hang_id := public.tim_dia_ban_giao_nhan(
    NEW.nguoi_nhan_dia_chi, NEW.khu_vuc_giao_hang_id);

  -- Không tự gán nhân viên. Nhân viên lấy hàng tự chọn đơn; nhân viên giao
  -- hàng quét mã kiện ở kho. Hai thao tác nhận được khóa nguyên tử bằng RPC.
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_phan_cong_nhan_vien_chang_cuoi ON public.don_hang;
CREATE TRIGGER trg_phan_cong_nhan_vien_chang_cuoi
BEFORE INSERT OR UPDATE OF trang_thai,kho_gui_id,kho_dich_id,nguoi_gui_dia_chi,nguoi_nhan_dia_chi,nhan_vien_lay_hang_id,nhan_vien_giao_hang_id ON public.don_hang
FOR EACH ROW EXECUTE FUNCTION public.phan_cong_nhan_vien_chang_cuoi();

CREATE OR REPLACE FUNCTION public.tai_phan_cong_khi_nhan_vien_thay_doi()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF TG_OP='UPDATE' AND OLD.vai_tro='NHAN_VIEN_LAY_HANG'
     AND (NEW.trang_thai<>'HOAT_DONG' OR NEW.trang_thai_duyet<>'DA_DUYET'
          OR NEW.kho_hang_id IS DISTINCT FROM OLD.kho_hang_id
          OR NEW.khu_vuc_id IS DISTINCT FROM OLD.khu_vuc_id) THEN
    UPDATE public.don_hang SET nhan_vien_lay_hang_id=NULL
    WHERE nhan_vien_lay_hang_id=OLD.id AND trang_thai='CHO_LAY_HANG';
  END IF;
  IF TG_OP='UPDATE' AND OLD.vai_tro='NHAN_VIEN_GIAO_HANG'
     AND (NEW.trang_thai<>'HOAT_DONG' OR NEW.trang_thai_duyet<>'DA_DUYET'
          OR NEW.kho_hang_id IS DISTINCT FROM OLD.kho_hang_id
          OR NEW.khu_vuc_id IS DISTINCT FROM OLD.khu_vuc_id) THEN
    UPDATE public.don_hang SET nhan_vien_giao_hang_id=NULL
    WHERE nhan_vien_giao_hang_id=OLD.id
      AND trang_thai IN ('DEN_KHO_DICH','GIAO_CHO_SHIPPER');
  END IF;
  IF NEW.trang_thai='HOAT_DONG' AND NEW.trang_thai_duyet='DA_DUYET' THEN
    IF NEW.vai_tro='NHAN_VIEN_LAY_HANG' THEN
      UPDATE public.don_hang SET nhan_vien_lay_hang_id=NULL
      WHERE kho_gui_id=NEW.kho_hang_id AND khu_vuc_lay_hang_id=NEW.khu_vuc_id
        AND nhan_vien_lay_hang_id IS NULL AND trang_thai='CHO_LAY_HANG';
    ELSIF NEW.vai_tro='NHAN_VIEN_GIAO_HANG' THEN
      UPDATE public.don_hang SET nhan_vien_giao_hang_id=NULL
      WHERE kho_dich_id=NEW.kho_hang_id AND khu_vuc_giao_hang_id=NEW.khu_vuc_id
        AND nhan_vien_giao_hang_id IS NULL
        AND trang_thai IN ('DEN_KHO_DICH','GIAO_CHO_SHIPPER');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_tai_phan_cong_khi_nhan_vien_thay_doi ON public.nhan_vien;
CREATE TRIGGER trg_tai_phan_cong_khi_nhan_vien_thay_doi
AFTER INSERT OR UPDATE OF vai_tro,kho_hang_id,khu_vuc_id,trang_thai_duyet,trang_thai
ON public.nhan_vien FOR EACH ROW EXECUTE FUNCTION public.tai_phan_cong_khi_nhan_vien_thay_doi();

-- Bản mới không tự tái phân công theo tải công việc.
DROP TRIGGER IF EXISTS trg_tai_phan_cong_khi_nhan_vien_thay_doi ON public.nhan_vien;

-- Phân công cả các đơn đang chờ tồn tại trước khi cài bản nâng cấp.
UPDATE public.don_hang SET nhan_vien_lay_hang_id=NULL
WHERE trang_thai='CHO_LAY_HANG';
UPDATE public.don_hang SET nhan_vien_giao_hang_id=NULL
WHERE trang_thai IN ('DEN_KHO_DICH','GIAO_CHO_SHIPPER');

CREATE OR REPLACE FUNCTION public.nhan_vien_chang_cuoi_cong_viec_v2()
RETURNS TABLE(id BIGINT,ma_van_don VARCHAR,ma_qr UUID,loai_cong_viec TEXT,ten_khach TEXT,
  so_dien_thoai TEXT,dia_chi TEXT,ten_kho TEXT,trang_thai VARCHAR,da_nhan BOOLEAN,ngay_cap_nhat TIMESTAMPTZ)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv WHERE nv.auth_user_id=auth.uid()
    AND nv.vai_tro IN ('NHAN_VIEN_LAY_HANG','NHAN_VIEN_GIAO_HANG')
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF NOT FOUND THEN RAISE EXCEPTION 'Tài khoản chưa được duyệt hoặc không đúng vai trò'; END IF;
  RETURN QUERY
  SELECT dh.id,dh.ma_van_don::VARCHAR,dh.ma_qr,
    CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN 'LAY_HANG' ELSE 'GIAO_HANG' END,
    CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN dh.nguoi_gui_ten ELSE dh.nguoi_nhan_ten END,
    CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN dh.nguoi_gui_sdt ELSE dh.nguoi_nhan_sdt END,
    CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN dh.nguoi_gui_dia_chi ELSE dh.nguoi_nhan_dia_chi END,
    kh.ten_kho::TEXT,dh.trang_thai::VARCHAR,
    CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN dh.nhan_vien_lay_hang_id=v_nv.id
         ELSE dh.nhan_vien_giao_hang_id=v_nv.id END,dh.ngay_cap_nhat
  FROM public.don_hang dh
  JOIN public.kho_hang kh ON kh.id=CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN dh.kho_gui_id ELSE dh.kho_dich_id END
  WHERE (v_nv.vai_tro='NHAN_VIEN_LAY_HANG' AND dh.kho_gui_id=v_nv.kho_hang_id
         AND dh.khu_vuc_lay_hang_id=v_nv.khu_vuc_id
         AND dh.dia_ban_lay_hang_id=v_nv.dia_ban_giao_nhan_id AND dh.trang_thai='CHO_LAY_HANG'
         AND (dh.nhan_vien_lay_hang_id IS NULL OR dh.nhan_vien_lay_hang_id=v_nv.id))
     OR (v_nv.vai_tro='NHAN_VIEN_GIAO_HANG' AND dh.nhan_vien_giao_hang_id=v_nv.id
         AND dh.trang_thai IN ('DEN_KHO_DICH','GIAO_CHO_SHIPPER','DANG_GIAO_HANG'))
  ORDER BY dh.ngay_cap_nhat;
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_lay_hang_nhan_don(p_don_hang_id BIGINT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE; v_id BIGINT;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv WHERE nv.auth_user_id=auth.uid()
    AND nv.vai_tro='NHAN_VIEN_LAY_HANG' AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF NOT FOUND THEN RAISE EXCEPTION 'Tài khoản không phải nhân viên lấy hàng đang hoạt động'; END IF;
  UPDATE public.don_hang dh SET nhan_vien_lay_hang_id=v_nv.id,nhan_vien_hien_tai_id=v_nv.id,ngay_cap_nhat=NOW()
  WHERE dh.id=p_don_hang_id AND dh.trang_thai='CHO_LAY_HANG'
    AND dh.kho_gui_id=v_nv.kho_hang_id AND dh.khu_vuc_lay_hang_id=v_nv.khu_vuc_id
    AND dh.dia_ban_lay_hang_id=v_nv.dia_ban_giao_nhan_id
    AND dh.nhan_vien_lay_hang_id IS NULL RETURNING dh.id INTO v_id;
  IF v_id IS NULL THEN
    IF EXISTS(SELECT 1 FROM public.don_hang dh WHERE dh.id=p_don_hang_id AND dh.nhan_vien_lay_hang_id=v_nv.id) THEN RETURN; END IF;
    RAISE EXCEPTION 'Đơn đã được nhân viên khác nhận hoặc không thuộc khu vực của bạn';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_giao_hang_quet_kien(p_ma TEXT)
RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE; v_don public.don_hang%ROWTYPE;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv WHERE nv.auth_user_id=auth.uid()
    AND nv.vai_tro='NHAN_VIEN_GIAO_HANG' AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF NOT FOUND THEN RAISE EXCEPTION 'Tài khoản không phải nhân viên giao hàng đang hoạt động'; END IF;
  SELECT dh.* INTO v_don FROM public.don_hang dh
  WHERE dh.ma_qr::TEXT=BTRIM(p_ma) OR UPPER(dh.ma_van_don)=UPPER(BTRIM(p_ma)) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy kiện hàng'; END IF;
  IF v_don.kho_dich_id<>v_nv.kho_hang_id
     OR v_don.khu_vuc_giao_hang_id<>v_nv.khu_vuc_id
     OR v_don.dia_ban_giao_hang_id<>v_nv.dia_ban_giao_nhan_id THEN
    RAISE EXCEPTION 'Kiện hàng không thuộc khu phố/ấp/thôn bạn phụ trách';
  END IF;
  IF v_don.trang_thai NOT IN ('DEN_KHO_DICH','GIAO_CHO_SHIPPER') THEN
    RAISE EXCEPTION 'Kiện hàng chưa sẵn sàng để giao';
  END IF;
  IF v_don.nhan_vien_giao_hang_id IS NOT NULL AND v_don.nhan_vien_giao_hang_id<>v_nv.id THEN
    RAISE EXCEPTION 'Kiện hàng đã được nhân viên khác quét nhận';
  END IF;
  UPDATE public.don_hang SET nhan_vien_giao_hang_id=v_nv.id,nhan_vien_hien_tai_id=v_nv.id,
    trang_thai='GIAO_CHO_SHIPPER',ngay_cap_nhat=NOW() WHERE id=v_don.id;
  RETURN v_don.id;
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_chang_cuoi_xac_nhan(p_don_hang_id BIGINT)
RETURNS VARCHAR LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE; v_don public.don_hang%ROWTYPE; v_moi VARCHAR;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv WHERE nv.auth_user_id=auth.uid()
    AND nv.vai_tro IN ('NHAN_VIEN_LAY_HANG','NHAN_VIEN_GIAO_HANG')
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  SELECT * INTO v_don FROM public.don_hang WHERE id=p_don_hang_id FOR UPDATE;
  IF v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN
    IF v_don.nhan_vien_lay_hang_id<>v_nv.id OR v_don.trang_thai<>'CHO_LAY_HANG' THEN
      RAISE EXCEPTION 'Đơn không thuộc địa bàn lấy hàng của bạn';
    END IF;
    v_moi := 'DA_LAY_HANG';
    UPDATE public.don_hang SET trang_thai=v_moi,kho_hien_tai_id=NULL,
      nhan_vien_hien_tai_id=v_nv.id,ngay_lay_hang=NOW(),ngay_cap_nhat=NOW() WHERE id=p_don_hang_id;
  ELSE
    IF v_don.nhan_vien_giao_hang_id<>v_nv.id OR v_don.trang_thai NOT IN ('DEN_KHO_DICH','GIAO_CHO_SHIPPER','DANG_GIAO_HANG') THEN
      RAISE EXCEPTION 'Đơn không thuộc địa bàn giao hàng của bạn';
    END IF;
    v_moi := CASE WHEN v_don.trang_thai='DANG_GIAO_HANG' THEN 'DA_GIAO_HANG' ELSE 'DANG_GIAO_HANG' END;
    UPDATE public.don_hang SET trang_thai=v_moi,nhan_vien_hien_tai_id=v_nv.id,
      ngay_giao_hang=CASE WHEN v_moi='DA_GIAO_HANG' THEN NOW() ELSE ngay_giao_hang END,
      ngay_cap_nhat=NOW() WHERE id=p_don_hang_id;
  END IF;
  RETURN v_moi;
END;
$$;

CREATE OR REPLACE FUNCTION public.danh_sach_khu_vuc_phan_cong()
RETURNS TABLE(id BIGINT,ten_khu_vuc VARCHAR,tinh_thanh VARCHAR,phuong_xa VARCHAR)
LANGUAGE sql SECURITY DEFINER STABLE SET search_path=public AS $$
  SELECT kv.id,kv.ten_khu_vuc,kv.tinh_thanh,kv.phuong_xa FROM public.khu_vuc kv
  WHERE auth.uid() IS NOT NULL ORDER BY kv.tinh_thanh,kv.phuong_xa
$$;

CREATE OR REPLACE FUNCTION public.danh_sach_dia_ban_giao_nhan(
  p_khu_vuc_id BIGINT
) RETURNS TABLE(id BIGINT,ten_dia_ban VARCHAR,loai_dia_ban VARCHAR)
LANGUAGE sql SECURITY DEFINER STABLE SET search_path=public AS $$
  SELECT db.id,db.ten_dia_ban,db.loai_dia_ban
  FROM public.dia_ban_giao_nhan db
  WHERE db.khu_vuc_id=p_khu_vuc_id AND db.trang_thai='HOAT_DONG'
    AND auth.uid() IS NOT NULL
  ORDER BY public.bo_dau_lower(db.ten_dia_ban),db.id
$$;

CREATE OR REPLACE FUNCTION public.luu_dia_ban_giao_nhan(
  p_khu_vuc_id BIGINT, p_ten_dia_ban TEXT
) RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  v_id BIGINT;
  v_phuong_xa TEXT;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.nhan_vien nv
    WHERE nv.auth_user_id=auth.uid()
      AND nv.vai_tro IN ('ADMIN','QUAN_LY_KHO')
      AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG'
  ) THEN
    RAISE EXCEPTION 'Bạn không có quyền thêm địa bàn';
  END IF;
  IF BTRIM(COALESCE(p_ten_dia_ban,''))='' THEN
    RAISE EXCEPTION 'Tên khu phố/ấp/thôn không được trống';
  END IF;
  SELECT kv.phuong_xa INTO v_phuong_xa FROM public.khu_vuc kv WHERE kv.id=p_khu_vuc_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phường/xã không tồn tại'; END IF;
  INSERT INTO public.dia_ban_giao_nhan(khu_vuc_id,ten_dia_ban,loai_dia_ban)
  VALUES (
    p_khu_vuc_id,BTRIM(p_ten_dia_ban),
    CASE WHEN public.bo_dau_lower(v_phuong_xa) LIKE 'xa %' THEN 'AP_THON' ELSE 'KHU_PHO' END
  )
  ON CONFLICT (khu_vuc_id,ten_dia_ban)
  DO UPDATE SET trang_thai='HOAT_DONG'
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;

ALTER TABLE public.dia_ban_giao_nhan ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS dia_ban_giao_nhan_doc ON public.dia_ban_giao_nhan;
CREATE POLICY dia_ban_giao_nhan_doc ON public.dia_ban_giao_nhan
FOR SELECT TO authenticated USING (TRUE);

REVOKE ALL ON FUNCTION public.nhan_vien_chang_cuoi_cong_viec_v2() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.nhan_vien_chang_cuoi_xac_nhan(BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.nhan_vien_lay_hang_nhan_don(BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.nhan_vien_giao_hang_quet_kien(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.nhan_vien_chang_cuoi_cong_viec_v2() TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_chang_cuoi_xac_nhan(BIGINT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_lay_hang_nhan_don(BIGINT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_giao_hang_quet_kien(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.danh_sach_khu_vuc_phan_cong() TO authenticated;
GRANT EXECUTE ON FUNCTION public.danh_sach_dia_ban_giao_nhan(BIGINT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.luu_dia_ban_giao_nhan(BIGINT,TEXT) TO authenticated;
NOTIFY pgrst,'reload schema';


-- ============================================================
-- GO TINH NANG DIA BAN NHO - SU DUNG API PHUONG/XA
-- ============================================================
-- Go tinh nang khu pho/ap/thon, quay lai phan cong theo phuong/xa.
-- KHONG xoa don hang, khach hang hoac nhan vien.

DROP FUNCTION IF EXISTS public.danh_sach_dia_ban_giao_nhan(BIGINT);
DROP FUNCTION IF EXISTS public.luu_dia_ban_giao_nhan(BIGINT,TEXT);
DROP FUNCTION IF EXISTS public.tim_dia_ban_giao_nhan(TEXT,BIGINT);

ALTER TABLE public.nhan_vien
  DROP COLUMN IF EXISTS dia_ban_giao_nhan_id;

ALTER TABLE public.don_hang
  DROP COLUMN IF EXISTS dia_ban_lay_hang_id,
  DROP COLUMN IF EXISTS dia_ban_giao_hang_id;

DROP TABLE IF EXISTS public.dia_ban_giao_nhan;

CREATE OR REPLACE FUNCTION public.kiem_tra_dia_ban_nhan_vien_chang_cuoi()
RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public AS $$
DECLARE
  v_kho_cap SMALLINT;
  v_kho_tinh_thanh TEXT;
  v_nhan_vien_tinh_thanh TEXT;
BEGIN
  IF NEW.vai_tro NOT IN ('NHAN_VIEN_LAY_HANG','NHAN_VIEN_GIAO_HANG') THEN
    RETURN NEW;
  END IF;
  IF NEW.kho_hang_id IS NULL OR NEW.khu_vuc_id IS NULL THEN
    RAISE EXCEPTION 'Nhân viên lấy/giao hàng phải có kho cấp 2 và phường/xã phụ trách';
  END IF;
  SELECT kh.cap_kho,kv.tinh_thanh
  INTO v_kho_cap,v_kho_tinh_thanh
  FROM public.kho_hang kh
  JOIN public.khu_vuc kv ON kv.id=kh.khu_vuc_id
  WHERE kh.id=NEW.kho_hang_id;
  IF v_kho_cap IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION 'Nhân viên lấy/giao hàng chỉ được gán vào kho cấp 2';
  END IF;
  SELECT kv.tinh_thanh INTO v_nhan_vien_tinh_thanh
  FROM public.khu_vuc kv WHERE kv.id=NEW.khu_vuc_id;
  IF public.bo_dau_lower(v_kho_tinh_thanh)
     IS DISTINCT FROM public.bo_dau_lower(v_nhan_vien_tinh_thanh) THEN
    RAISE EXCEPTION 'Phường/xã phụ trách phải cùng tỉnh/thành với kho cấp 2';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_kiem_tra_dia_ban_nhan_vien_chang_cuoi
ON public.nhan_vien;
CREATE TRIGGER trg_kiem_tra_dia_ban_nhan_vien_chang_cuoi
BEFORE INSERT OR UPDATE OF vai_tro,kho_hang_id,khu_vuc_id
ON public.nhan_vien
FOR EACH ROW EXECUTE FUNCTION public.kiem_tra_dia_ban_nhan_vien_chang_cuoi();

CREATE OR REPLACE FUNCTION public.phan_cong_nhan_vien_chang_cuoi()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF NEW.khu_vuc_lay_hang_id IS NULL THEN
    NEW.khu_vuc_lay_hang_id := public.tim_khu_vuc_theo_dia_chi(NEW.nguoi_gui_dia_chi);
  END IF;
  IF NEW.khu_vuc_giao_hang_id IS NULL THEN
    NEW.khu_vuc_giao_hang_id := public.tim_khu_vuc_theo_dia_chi(NEW.nguoi_nhan_dia_chi);
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_chang_cuoi_cong_viec_v2()
RETURNS TABLE(id BIGINT,ma_van_don VARCHAR,ma_qr UUID,loai_cong_viec TEXT,
  ten_khach TEXT,so_dien_thoai TEXT,dia_chi TEXT,ten_kho TEXT,
  trang_thai VARCHAR,da_nhan BOOLEAN,ngay_cap_nhat TIMESTAMPTZ)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid()
    AND nv.vai_tro IN ('NHAN_VIEN_LAY_HANG','NHAN_VIEN_GIAO_HANG')
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tài khoản chưa được duyệt hoặc không đúng vai trò';
  END IF;
  RETURN QUERY
  SELECT dh.id,dh.ma_van_don::VARCHAR,dh.ma_qr,
    CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN 'LAY_HANG' ELSE 'GIAO_HANG' END,
    CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN dh.nguoi_gui_ten ELSE dh.nguoi_nhan_ten END,
    CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN dh.nguoi_gui_sdt ELSE dh.nguoi_nhan_sdt END,
    CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN dh.nguoi_gui_dia_chi ELSE dh.nguoi_nhan_dia_chi END,
    kh.ten_kho::TEXT,dh.trang_thai::VARCHAR,
    CASE WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG'
      THEN dh.nhan_vien_lay_hang_id=v_nv.id
      ELSE dh.nhan_vien_giao_hang_id=v_nv.id END,
    dh.ngay_cap_nhat
  FROM public.don_hang dh
  JOIN public.kho_hang kh ON kh.id=CASE
    WHEN v_nv.vai_tro='NHAN_VIEN_LAY_HANG' THEN dh.kho_gui_id
    ELSE dh.kho_dich_id END
  WHERE (v_nv.vai_tro='NHAN_VIEN_LAY_HANG'
         AND dh.kho_gui_id=v_nv.kho_hang_id
         AND dh.khu_vuc_lay_hang_id=v_nv.khu_vuc_id
         AND dh.trang_thai='CHO_LAY_HANG'
         AND (dh.nhan_vien_lay_hang_id IS NULL OR dh.nhan_vien_lay_hang_id=v_nv.id))
     OR (v_nv.vai_tro='NHAN_VIEN_GIAO_HANG'
         AND dh.nhan_vien_giao_hang_id=v_nv.id
         AND dh.trang_thai IN ('DEN_KHO_DICH','GIAO_CHO_SHIPPER','DANG_GIAO_HANG'))
  ORDER BY dh.ngay_cap_nhat;
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_lay_hang_nhan_don(p_don_hang_id BIGINT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE; v_id BIGINT;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid()
    AND nv.vai_tro='NHAN_VIEN_LAY_HANG'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tài khoản không phải nhân viên lấy hàng đang hoạt động';
  END IF;
  UPDATE public.don_hang dh
  SET nhan_vien_lay_hang_id=v_nv.id,nhan_vien_hien_tai_id=v_nv.id,
      ngay_cap_nhat=NOW()
  WHERE dh.id=p_don_hang_id AND dh.trang_thai='CHO_LAY_HANG'
    AND dh.kho_gui_id=v_nv.kho_hang_id
    AND dh.khu_vuc_lay_hang_id=v_nv.khu_vuc_id
    AND dh.nhan_vien_lay_hang_id IS NULL
  RETURNING dh.id INTO v_id;
  IF v_id IS NULL THEN
    IF EXISTS(SELECT 1 FROM public.don_hang dh
      WHERE dh.id=p_don_hang_id AND dh.nhan_vien_lay_hang_id=v_nv.id) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Đơn đã được nhân viên khác nhận hoặc không thuộc phường/xã của bạn';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_giao_hang_quet_kien(p_ma TEXT)
RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE; v_don public.don_hang%ROWTYPE;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid()
    AND nv.vai_tro='NHAN_VIEN_GIAO_HANG'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tài khoản không phải nhân viên giao hàng đang hoạt động';
  END IF;
  SELECT dh.* INTO v_don FROM public.don_hang dh
  WHERE dh.ma_qr::TEXT=BTRIM(p_ma)
     OR UPPER(dh.ma_van_don)=UPPER(BTRIM(p_ma)) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy kiện hàng'; END IF;
  IF v_don.kho_dich_id<>v_nv.kho_hang_id
     OR v_don.khu_vuc_giao_hang_id<>v_nv.khu_vuc_id THEN
    RAISE EXCEPTION 'Kiện hàng không thuộc kho hoặc phường/xã bạn phụ trách';
  END IF;
  IF v_don.trang_thai NOT IN ('DEN_KHO_DICH','GIAO_CHO_SHIPPER') THEN
    RAISE EXCEPTION 'Kiện hàng chưa sẵn sàng để giao';
  END IF;
  IF v_don.nhan_vien_giao_hang_id IS NOT NULL
     AND v_don.nhan_vien_giao_hang_id<>v_nv.id THEN
    RAISE EXCEPTION 'Kiện hàng đã được nhân viên khác quét nhận';
  END IF;
  UPDATE public.don_hang
  SET nhan_vien_giao_hang_id=v_nv.id,nhan_vien_hien_tai_id=v_nv.id,
      trang_thai='GIAO_CHO_SHIPPER',ngay_cap_nhat=NOW()
  WHERE id=v_don.id;
  RETURN v_don.id;
END;
$$;

NOTIFY pgrst,'reload schema';
\n+-- ============================================================
-- NANG CAP GAN XE, CHUYEN XE VA QUET QR TAI KHO
-- ============================================================
-- Quan ly kho gan xe/chuyen va nhan vien kho quet kien.
-- Ban nang cap an toan, khong xoa du lieu.

CREATE OR REPLACE FUNCTION public.quan_ly_kho_danh_sach_xe(p_kho_id BIGINT)
RETURNS TABLE(id BIGINT,bien_so_xe VARCHAR,tai_trong NUMERIC,trang_thai VARCHAR,
  tai_xe_id BIGINT,ten_tai_xe VARCHAR,so_dien_thoai VARCHAR)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
BEGIN
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_id) THEN
    RAISE EXCEPTION 'Kho không thuộc phạm vi quản lý';
  END IF;
  RETURN QUERY
  SELECT x.id,x.bien_so_xe::VARCHAR,x.tai_trong,x.trang_thai::VARCHAR,
    x.tai_xe_id,nv.ho_ten::VARCHAR,nv.so_dien_thoai::VARCHAR
  FROM public.xe x
  JOIN public.nhan_vien nv ON nv.id=x.tai_xe_id
  WHERE nv.kho_hang_id=p_kho_id AND nv.vai_tro='VAN_CHUYEN'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG'
  ORDER BY CASE x.trang_thai WHEN 'SAN_SANG' THEN 0 ELSE 1 END,x.bien_so_xe;
END;
$$;

CREATE OR REPLACE FUNCTION public.quan_ly_kho_danh_sach_chuyen(p_kho_id BIGINT)
RETURNS TABLE(id BIGINT,ma_chuyen VARCHAR,trang_thai VARCHAR,xe_id BIGINT,
  bien_so_xe VARCHAR,ten_tai_xe VARCHAR,kho_di_id BIGINT,ten_kho_di VARCHAR,
  kho_den_id BIGINT,ten_kho_den VARCHAR,ngay_du_kien TIMESTAMPTZ,
  so_kien BIGINT)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
BEGIN
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_id) THEN
    RAISE EXCEPTION 'Kho không thuộc phạm vi quản lý';
  END IF;
  RETURN QUERY
  SELECT cx.id,cx.ma_chuyen::VARCHAR,cx.trang_thai::VARCHAR,cx.xe_id,
    x.bien_so_xe::VARCHAR,nv.ho_ten::VARCHAR,c.kho_di_id,kd.ten_kho::VARCHAR,
    c.kho_den_id,kn.ten_kho::VARCHAR,cx.ngay_du_kien,
    (SELECT COUNT(*) FROM public.chi_tiet_chuyen_xe ct
      WHERE ct.chuyen_xe_id=cx.id)::BIGINT
  FROM public.chuyen_xe cx
  JOIN public.xe x ON x.id=cx.xe_id
  LEFT JOIN public.nhan_vien nv ON nv.id=x.tai_xe_id
  JOIN public.chuyen_xe_chang c ON c.chuyen_xe_id=cx.id AND c.thu_tu_chuyen=1
  JOIN public.kho_hang kd ON kd.id=c.kho_di_id
  JOIN public.kho_hang kn ON kn.id=c.kho_den_id
  WHERE c.kho_di_id=p_kho_id OR c.kho_den_id=p_kho_id
  ORDER BY cx.ngay_tao DESC LIMIT 200;
END;
$$;

CREATE OR REPLACE FUNCTION public.quan_ly_kho_gan_xe_tao_chuyen(
  p_kho_di_id BIGINT,p_kho_den_id BIGINT,p_xe_id BIGINT,
  p_ngay_du_kien TIMESTAMPTZ DEFAULT NULL
) RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv_id BIGINT; v_chuyen_id BIGINT; v_ma VARCHAR;
BEGIN
  IF p_kho_di_id=p_kho_den_id THEN RAISE EXCEPTION 'Kho đi và kho đến phải khác nhau'; END IF;
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_di_id) THEN
    RAISE EXCEPTION 'Bạn không quản lý kho khởi hành';
  END IF;
  SELECT nv.id INTO v_nv_id FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid() AND nv.vai_tro='QUAN_LY_KHO'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF v_nv_id IS NULL THEN RAISE EXCEPTION 'Tài khoản không phải quản lý kho'; END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.xe x JOIN public.nhan_vien tx ON tx.id=x.tai_xe_id
    WHERE x.id=p_xe_id AND x.trang_thai='SAN_SANG'
      AND tx.kho_hang_id=p_kho_di_id AND tx.vai_tro='VAN_CHUYEN'
  ) THEN RAISE EXCEPTION 'Xe không sẵn sàng hoặc không thuộc kho khởi hành'; END IF;
  IF EXISTS(SELECT 1 FROM public.chuyen_xe cx WHERE cx.xe_id=p_xe_id
    AND cx.trang_thai IN ('CHO_KHOI_HANH','DANG_XEP_HANG','DANG_DI')) THEN
    RAISE EXCEPTION 'Xe đang có chuyến chưa hoàn thành';
  END IF;
  v_ma := 'CX' || TO_CHAR(NOW(),'YYMMDDHH24MISS') || UPPER(SUBSTR(REPLACE(gen_random_uuid()::TEXT,'-',''),1,5));
  INSERT INTO public.chuyen_xe(xe_id,ma_chuyen,trang_thai,ngay_du_kien)
  VALUES(p_xe_id,v_ma,'CHO_KHOI_HANH',p_ngay_du_kien) RETURNING id INTO v_chuyen_id;
  INSERT INTO public.chuyen_xe_chang(chuyen_xe_id,thu_tu_chuyen,kho_di_id,
    kho_den_id,nguoi_phan_cong_id,ngay_den_du_kien)
  VALUES(v_chuyen_id,1,p_kho_di_id,p_kho_den_id,v_nv_id,p_ngay_du_kien);
  RETURN v_chuyen_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_kho_danh_sach_chuyen()
RETURNS TABLE(id BIGINT,ma_chuyen VARCHAR,trang_thai VARCHAR,bien_so_xe VARCHAR,
  ten_tai_xe VARCHAR,kho_di_id BIGINT,ten_kho_di VARCHAR,kho_den_id BIGINT,
  ten_kho_den VARCHAR,so_kien BIGINT)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_kho_id BIGINT;
BEGIN
  SELECT nv.kho_hang_id INTO v_kho_id FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid() AND nv.vai_tro='NHAN_VIEN_KHO'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF v_kho_id IS NULL THEN RAISE EXCEPTION 'Nhân viên chưa được gán kho'; END IF;
  RETURN QUERY
  SELECT cx.id,cx.ma_chuyen::VARCHAR,cx.trang_thai::VARCHAR,x.bien_so_xe::VARCHAR,
    tx.ho_ten::VARCHAR,c.kho_di_id,kd.ten_kho::VARCHAR,c.kho_den_id,
    kn.ten_kho::VARCHAR,(SELECT COUNT(*) FROM public.chi_tiet_chuyen_xe ct
      WHERE ct.chuyen_xe_id=cx.id)::BIGINT
  FROM public.chuyen_xe cx JOIN public.xe x ON x.id=cx.xe_id
  LEFT JOIN public.nhan_vien tx ON tx.id=x.tai_xe_id
  JOIN public.chuyen_xe_chang c ON c.chuyen_xe_id=cx.id AND c.thu_tu_chuyen=1
  JOIN public.kho_hang kd ON kd.id=c.kho_di_id JOIN public.kho_hang kn ON kn.id=c.kho_den_id
  WHERE (c.kho_di_id=v_kho_id AND cx.trang_thai IN ('CHO_KHOI_HANH','DANG_XEP_HANG'))
     OR (c.kho_den_id=v_kho_id AND cx.trang_thai IN ('DANG_DI','DA_DEN'))
  ORDER BY cx.ngay_tao DESC;
END;
$$;

-- Nhận kiện do nhân viên lấy hàng đưa về kho. Thao tác này không cần chọn chuyến xe.
CREATE OR REPLACE FUNCTION public.nhan_vien_kho_nhap_kien(p_ma TEXT)
RETURNS VARCHAR LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE; v_don public.don_hang%ROWTYPE;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid() AND nv.vai_tro='NHAN_VIEN_KHO'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF NOT FOUND OR v_nv.kho_hang_id IS NULL THEN
    RAISE EXCEPTION 'Nhân viên chưa được gán kho';
  END IF;

  SELECT dh.* INTO v_don FROM public.don_hang dh
  WHERE dh.ma_qr::TEXT=BTRIM(p_ma) OR UPPER(dh.ma_van_don)=UPPER(BTRIM(p_ma))
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy kiện hàng'; END IF;
  IF v_don.kho_gui_id<>v_nv.kho_hang_id AND v_don.kho_dich_id<>v_nv.kho_hang_id THEN
    RAISE EXCEPTION 'Kiện hàng không thuộc tuyến của kho này';
  END IF;
  IF v_don.trang_thai NOT IN ('DA_LAY_HANG','DANG_VAN_CHUYEN','DEN_KHO_TRUNG_CHUYEN') THEN
    RAISE EXCEPTION 'Trạng thái kiện hàng không cho phép nhập kho';
  END IF;

  UPDATE public.don_hang SET
    kho_hien_tai_id=v_nv.kho_hang_id,
    nhan_vien_hien_tai_id=v_nv.id,
    trang_thai=CASE WHEN kho_dich_id=v_nv.kho_hang_id
      THEN 'DEN_KHO_DICH' ELSE 'DEN_KHO_TRUNG_CHUYEN' END,
    ngay_cap_nhat=NOW()
  WHERE id=v_don.id;
  RETURN 'DA_NHAP_KHO';
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_kho_quet_kien_chuyen(
  p_chuyen_xe_id BIGINT,p_ma TEXT,p_thao_tac TEXT
) RETURNS VARCHAR LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE; v_don public.don_hang%ROWTYPE;
  v_chang public.chuyen_xe_chang%ROWTYPE; v_thao_tac TEXT; v_trang_thai VARCHAR;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid() AND nv.vai_tro='NHAN_VIEN_KHO'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF NOT FOUND OR v_nv.kho_hang_id IS NULL THEN RAISE EXCEPTION 'Nhân viên chưa được gán kho'; END IF;
  SELECT c.* INTO v_chang FROM public.chuyen_xe_chang c
  WHERE c.chuyen_xe_id=p_chuyen_xe_id AND c.thu_tu_chuyen=1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy chuyến xe'; END IF;
  SELECT dh.* INTO v_don FROM public.don_hang dh
  WHERE dh.ma_qr::TEXT=BTRIM(p_ma) OR UPPER(dh.ma_van_don)=UPPER(BTRIM(p_ma)) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy kiện hàng'; END IF;
  v_thao_tac := UPPER(BTRIM(p_thao_tac));
  IF v_thao_tac='XEP_LEN_XE' THEN
    IF v_chang.kho_di_id<>v_nv.kho_hang_id THEN RAISE EXCEPTION 'Chuyến xe không xuất phát từ kho của bạn'; END IF;
    IF v_don.kho_hien_tai_id IS DISTINCT FROM v_nv.kho_hang_id THEN RAISE EXCEPTION 'Kiện hàng chưa có trong kho này'; END IF;
    IF EXISTS(SELECT 1 FROM public.chi_tiet_chuyen_xe ct JOIN public.chuyen_xe cx ON cx.id=ct.chuyen_xe_id
      WHERE ct.don_hang_id=v_don.id AND cx.id<>p_chuyen_xe_id
        AND cx.trang_thai IN ('CHO_KHOI_HANH','DANG_XEP_HANG','DANG_DI')) THEN
      RAISE EXCEPTION 'Kiện hàng đã thuộc chuyến xe khác';
    END IF;
    INSERT INTO public.chi_tiet_chuyen_xe(chuyen_xe_id,don_hang_id,trang_thai)
    VALUES(p_chuyen_xe_id,v_don.id,'DA_XEP_HANG') ON CONFLICT(chuyen_xe_id,don_hang_id)
    DO UPDATE SET trang_thai='DA_XEP_HANG',ngay_xep_hang=NOW(),ngay_do_hang=NULL;
    UPDATE public.chuyen_xe SET trang_thai='DANG_XEP_HANG' WHERE id=p_chuyen_xe_id AND trang_thai='CHO_KHOI_HANH';
    v_trang_thai := 'DA_XEP_HANG';
  ELSIF v_thao_tac='NHAP_KHO' THEN
    IF v_chang.kho_den_id<>v_nv.kho_hang_id THEN RAISE EXCEPTION 'Chuyến xe không đến kho của bạn'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.chi_tiet_chuyen_xe ct WHERE ct.chuyen_xe_id=p_chuyen_xe_id AND ct.don_hang_id=v_don.id) THEN
      RAISE EXCEPTION 'Kiện hàng không thuộc chuyến xe này';
    END IF;
    UPDATE public.chi_tiet_chuyen_xe SET trang_thai='DA_DO_HANG',ngay_do_hang=NOW()
    WHERE chuyen_xe_id=p_chuyen_xe_id AND don_hang_id=v_don.id;
    UPDATE public.don_hang SET kho_hien_tai_id=v_nv.kho_hang_id,
      nhan_vien_hien_tai_id=v_nv.id,
      trang_thai=CASE WHEN kho_dich_id=v_nv.kho_hang_id THEN 'DEN_KHO_DICH' ELSE 'DEN_KHO_TRUNG_CHUYEN' END,
      ngay_cap_nhat=NOW() WHERE id=v_don.id;
    v_trang_thai := 'DA_NHAP_KHO';
  ELSE RAISE EXCEPTION 'Thao tác quét không hợp lệ';
  END IF;
  RETURN v_trang_thai;
END;
$$;

GRANT EXECUTE ON FUNCTION public.quan_ly_kho_danh_sach_xe(BIGINT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.quan_ly_kho_danh_sach_chuyen(BIGINT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.quan_ly_kho_gan_xe_tao_chuyen(BIGINT,BIGINT,BIGINT,TIMESTAMPTZ) TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_kho_danh_sach_chuyen() TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_kho_nhap_kien(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_kho_quet_kien_chuyen(BIGINT,TEXT,TEXT) TO authenticated;
NOTIFY pgrst,'reload schema';

+-- NANG CAP TUYEN KHO DEN THEO CAY QUAN LY
-- Quan ly kho gan xe/chuyen va nhan vien kho quet kien.
-- Ban nang cap an toan, khong xoa du lieu.

CREATE OR REPLACE FUNCTION public.quan_ly_kho_danh_sach_xe(p_kho_id BIGINT)
RETURNS TABLE(id BIGINT,bien_so_xe VARCHAR,tai_trong NUMERIC,trang_thai VARCHAR,
  tai_xe_id BIGINT,ten_tai_xe VARCHAR,so_dien_thoai VARCHAR)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
BEGIN
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_id) THEN
    RAISE EXCEPTION 'Kho không thuộc phạm vi quản lý';
  END IF;
  RETURN QUERY
  SELECT x.id,x.bien_so_xe::VARCHAR,x.tai_trong,x.trang_thai::VARCHAR,
    x.tai_xe_id,nv.ho_ten::VARCHAR,nv.so_dien_thoai::VARCHAR
  FROM public.xe x
  JOIN public.nhan_vien nv ON nv.id=x.tai_xe_id
  WHERE nv.kho_hang_id=p_kho_id AND nv.vai_tro='VAN_CHUYEN'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG'
  ORDER BY CASE x.trang_thai WHEN 'SAN_SANG' THEN 0 ELSE 1 END,x.bien_so_xe;
END;
$$;

-- Danh sách kho đến theo đúng cây vận chuyển:
-- cấp 2 chỉ đi lên kho cấp 1 trực thuộc;
-- cấp 1 đi xuống kho cấp 2 trực thuộc hoặc sang một kho cấp 1 khác.
CREATE OR REPLACE FUNCTION public.quan_ly_kho_danh_sach_kho_den(p_kho_di_id BIGINT)
RETURNS TABLE(id BIGINT,ma_kho VARCHAR,ten_kho VARCHAR,dia_chi TEXT,
  cap_kho SMALLINT,kho_trung_tam_id BIGINT)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_cap SMALLINT; v_kho_cha BIGINT;
BEGIN
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_di_id) THEN
    RAISE EXCEPTION 'Kho khởi hành không thuộc phạm vi quản lý';
  END IF;
  SELECT kh.cap_kho,kh.kho_trung_tam_id INTO v_cap,v_kho_cha
  FROM public.kho_hang kh WHERE kh.id=p_kho_di_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy kho khởi hành'; END IF;

  RETURN QUERY
  SELECT kh.id,kh.ma_kho::VARCHAR,kh.ten_kho::VARCHAR,kh.dia_chi,
    kh.cap_kho,kh.kho_trung_tam_id
  FROM public.kho_hang kh
  WHERE kh.id<>p_kho_di_id
    AND (
      -- Kho cấp 2 luôn nhìn thấy đúng kho cấp 1 cha để có thể gán xe trả hàng về.
      (v_cap=2 AND kh.id=v_kho_cha)
      OR
      (v_cap=1 AND kh.trang_thai='HOAT_DONG' AND (
        (kh.cap_kho=2 AND kh.kho_trung_tam_id=p_kho_di_id)
        OR kh.cap_kho=1
      ))
    )
  ORDER BY kh.cap_kho,kh.ten_kho;
END;
$$;

CREATE OR REPLACE FUNCTION public.quan_ly_kho_danh_sach_chuyen(p_kho_id BIGINT)
RETURNS TABLE(id BIGINT,ma_chuyen VARCHAR,trang_thai VARCHAR,xe_id BIGINT,
  bien_so_xe VARCHAR,ten_tai_xe VARCHAR,kho_di_id BIGINT,ten_kho_di VARCHAR,
  kho_den_id BIGINT,ten_kho_den VARCHAR,ngay_du_kien TIMESTAMPTZ,
  so_kien BIGINT)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
BEGIN
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_id) THEN
    RAISE EXCEPTION 'Kho không thuộc phạm vi quản lý';
  END IF;
  RETURN QUERY
  SELECT cx.id,cx.ma_chuyen::VARCHAR,cx.trang_thai::VARCHAR,cx.xe_id,
    x.bien_so_xe::VARCHAR,nv.ho_ten::VARCHAR,c.kho_di_id,kd.ten_kho::VARCHAR,
    c.kho_den_id,kn.ten_kho::VARCHAR,cx.ngay_du_kien,
    (SELECT COUNT(*) FROM public.chi_tiet_chuyen_xe ct
      WHERE ct.chuyen_xe_id=cx.id)::BIGINT
  FROM public.chuyen_xe cx
  JOIN public.xe x ON x.id=cx.xe_id
  LEFT JOIN public.nhan_vien nv ON nv.id=x.tai_xe_id
  JOIN public.chuyen_xe_chang c ON c.chuyen_xe_id=cx.id AND c.thu_tu_chuyen=1
  JOIN public.kho_hang kd ON kd.id=c.kho_di_id
  JOIN public.kho_hang kn ON kn.id=c.kho_den_id
  WHERE c.kho_di_id=p_kho_id OR c.kho_den_id=p_kho_id
  ORDER BY cx.ngay_tao DESC LIMIT 200;
END;
$$;

CREATE OR REPLACE FUNCTION public.quan_ly_kho_gan_xe_tao_chuyen(
  p_kho_di_id BIGINT,p_kho_den_id BIGINT,p_xe_id BIGINT,
  p_ngay_du_kien TIMESTAMPTZ DEFAULT NULL
) RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv_id BIGINT; v_chuyen_id BIGINT; v_ma VARCHAR;
BEGIN
  IF p_kho_di_id=p_kho_den_id THEN RAISE EXCEPTION 'Kho đi và kho đến phải khác nhau'; END IF;
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_di_id) THEN
    RAISE EXCEPTION 'Bạn không quản lý kho khởi hành';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.quan_ly_kho_danh_sach_kho_den(p_kho_di_id) d
    WHERE d.id=p_kho_den_id
  ) THEN
    RAISE EXCEPTION 'Kho đến không đúng tuyến được phép của kho khởi hành';
  END IF;
  SELECT nv.id INTO v_nv_id FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid() AND nv.vai_tro='QUAN_LY_KHO'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF v_nv_id IS NULL THEN RAISE EXCEPTION 'Tài khoản không phải quản lý kho'; END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.xe x JOIN public.nhan_vien tx ON tx.id=x.tai_xe_id
    WHERE x.id=p_xe_id AND x.trang_thai='SAN_SANG'
      AND tx.kho_hang_id=p_kho_di_id AND tx.vai_tro='VAN_CHUYEN'
  ) THEN RAISE EXCEPTION 'Xe không sẵn sàng hoặc không thuộc kho khởi hành'; END IF;
  IF EXISTS(SELECT 1 FROM public.chuyen_xe cx WHERE cx.xe_id=p_xe_id
    AND cx.trang_thai IN ('CHO_KHOI_HANH','DANG_XEP_HANG','DANG_DI')) THEN
    RAISE EXCEPTION 'Xe đang có chuyến chưa hoàn thành';
  END IF;
  v_ma := 'CX' || TO_CHAR(NOW(),'YYMMDDHH24MISS') || UPPER(SUBSTR(REPLACE(gen_random_uuid()::TEXT,'-',''),1,5));
  INSERT INTO public.chuyen_xe(xe_id,ma_chuyen,trang_thai,ngay_du_kien)
  VALUES(p_xe_id,v_ma,'CHO_KHOI_HANH',p_ngay_du_kien) RETURNING id INTO v_chuyen_id;
  INSERT INTO public.chuyen_xe_chang(chuyen_xe_id,thu_tu_chuyen,kho_di_id,
    kho_den_id,nguoi_phan_cong_id,ngay_den_du_kien)
  VALUES(v_chuyen_id,1,p_kho_di_id,p_kho_den_id,v_nv_id,p_ngay_du_kien);
  RETURN v_chuyen_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_kho_danh_sach_chuyen()
RETURNS TABLE(id BIGINT,ma_chuyen VARCHAR,trang_thai VARCHAR,bien_so_xe VARCHAR,
  ten_tai_xe VARCHAR,kho_di_id BIGINT,ten_kho_di VARCHAR,kho_den_id BIGINT,
  ten_kho_den VARCHAR,so_kien BIGINT)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_kho_id BIGINT;
BEGIN
  SELECT nv.kho_hang_id INTO v_kho_id FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid() AND nv.vai_tro='NHAN_VIEN_KHO'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF v_kho_id IS NULL THEN RAISE EXCEPTION 'Nhân viên chưa được gán kho'; END IF;
  RETURN QUERY
  SELECT cx.id,cx.ma_chuyen::VARCHAR,cx.trang_thai::VARCHAR,x.bien_so_xe::VARCHAR,
    tx.ho_ten::VARCHAR,c.kho_di_id,kd.ten_kho::VARCHAR,c.kho_den_id,
    kn.ten_kho::VARCHAR,(SELECT COUNT(*) FROM public.chi_tiet_chuyen_xe ct
      WHERE ct.chuyen_xe_id=cx.id)::BIGINT
  FROM public.chuyen_xe cx JOIN public.xe x ON x.id=cx.xe_id
  LEFT JOIN public.nhan_vien tx ON tx.id=x.tai_xe_id
  JOIN public.chuyen_xe_chang c ON c.chuyen_xe_id=cx.id AND c.thu_tu_chuyen=1
  JOIN public.kho_hang kd ON kd.id=c.kho_di_id JOIN public.kho_hang kn ON kn.id=c.kho_den_id
  WHERE (c.kho_di_id=v_kho_id AND cx.trang_thai IN ('CHO_KHOI_HANH','DANG_XEP_HANG'))
     OR (c.kho_den_id=v_kho_id AND cx.trang_thai IN ('DANG_DI','DA_DEN'))
  ORDER BY cx.ngay_tao DESC;
END;
$$;

-- Nhận kiện do nhân viên lấy hàng đưa về kho. Thao tác này không cần chọn chuyến xe.
CREATE OR REPLACE FUNCTION public.nhan_vien_kho_nhap_kien(p_ma TEXT)
RETURNS VARCHAR LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE; v_don public.don_hang%ROWTYPE;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid() AND nv.vai_tro='NHAN_VIEN_KHO'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF NOT FOUND OR v_nv.kho_hang_id IS NULL THEN
    RAISE EXCEPTION 'Nhân viên chưa được gán kho';
  END IF;

  SELECT dh.* INTO v_don FROM public.don_hang dh
  WHERE dh.ma_qr::TEXT=BTRIM(p_ma) OR UPPER(dh.ma_van_don)=UPPER(BTRIM(p_ma))
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy kiện hàng'; END IF;
  IF v_don.kho_gui_id<>v_nv.kho_hang_id AND v_don.kho_dich_id<>v_nv.kho_hang_id THEN
    RAISE EXCEPTION 'Kiện hàng không thuộc tuyến của kho này';
  END IF;
  IF v_don.trang_thai NOT IN ('DA_LAY_HANG','DANG_VAN_CHUYEN','DEN_KHO_TRUNG_CHUYEN') THEN
    RAISE EXCEPTION 'Trạng thái kiện hàng không cho phép nhập kho';
  END IF;

  UPDATE public.don_hang SET
    kho_hien_tai_id=v_nv.kho_hang_id,
    nhan_vien_hien_tai_id=v_nv.id,
    trang_thai=CASE WHEN kho_dich_id=v_nv.kho_hang_id
      THEN 'DEN_KHO_DICH' ELSE 'DEN_KHO_TRUNG_CHUYEN' END,
    ngay_cap_nhat=NOW()
  WHERE id=v_don.id;
  RETURN 'DA_NHAP_KHO';
END;
$$;

CREATE OR REPLACE FUNCTION public.nhan_vien_kho_quet_kien_chuyen(
  p_chuyen_xe_id BIGINT,p_ma TEXT,p_thao_tac TEXT
) RETURNS VARCHAR LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv public.nhan_vien%ROWTYPE; v_don public.don_hang%ROWTYPE;
  v_chang public.chuyen_xe_chang%ROWTYPE; v_thao_tac TEXT; v_trang_thai VARCHAR;
BEGIN
  SELECT nv.* INTO v_nv FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid() AND nv.vai_tro='NHAN_VIEN_KHO'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF NOT FOUND OR v_nv.kho_hang_id IS NULL THEN RAISE EXCEPTION 'Nhân viên chưa được gán kho'; END IF;
  SELECT c.* INTO v_chang FROM public.chuyen_xe_chang c
  WHERE c.chuyen_xe_id=p_chuyen_xe_id AND c.thu_tu_chuyen=1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy chuyến xe'; END IF;
  SELECT dh.* INTO v_don FROM public.don_hang dh
  WHERE dh.ma_qr::TEXT=BTRIM(p_ma) OR UPPER(dh.ma_van_don)=UPPER(BTRIM(p_ma)) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy kiện hàng'; END IF;
  v_thao_tac := UPPER(BTRIM(p_thao_tac));
  IF v_thao_tac='XEP_LEN_XE' THEN
    IF v_chang.kho_di_id<>v_nv.kho_hang_id THEN RAISE EXCEPTION 'Chuyến xe không xuất phát từ kho của bạn'; END IF;
    IF v_don.kho_hien_tai_id IS DISTINCT FROM v_nv.kho_hang_id THEN RAISE EXCEPTION 'Kiện hàng chưa có trong kho này'; END IF;
    IF EXISTS(SELECT 1 FROM public.chi_tiet_chuyen_xe ct JOIN public.chuyen_xe cx ON cx.id=ct.chuyen_xe_id
      WHERE ct.don_hang_id=v_don.id AND cx.id<>p_chuyen_xe_id
        AND cx.trang_thai IN ('CHO_KHOI_HANH','DANG_XEP_HANG','DANG_DI')) THEN
      RAISE EXCEPTION 'Kiện hàng đã thuộc chuyến xe khác';
    END IF;
    INSERT INTO public.chi_tiet_chuyen_xe(chuyen_xe_id,don_hang_id,trang_thai)
    VALUES(p_chuyen_xe_id,v_don.id,'DA_XEP_HANG') ON CONFLICT(chuyen_xe_id,don_hang_id)
    DO UPDATE SET trang_thai='DA_XEP_HANG',ngay_xep_hang=NOW(),ngay_do_hang=NULL;
    UPDATE public.chuyen_xe SET trang_thai='DANG_XEP_HANG' WHERE id=p_chuyen_xe_id AND trang_thai='CHO_KHOI_HANH';
    v_trang_thai := 'DA_XEP_HANG';
  ELSIF v_thao_tac='NHAP_KHO' THEN
    IF v_chang.kho_den_id<>v_nv.kho_hang_id THEN RAISE EXCEPTION 'Chuyến xe không đến kho của bạn'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.chi_tiet_chuyen_xe ct WHERE ct.chuyen_xe_id=p_chuyen_xe_id AND ct.don_hang_id=v_don.id) THEN
      RAISE EXCEPTION 'Kiện hàng không thuộc chuyến xe này';
    END IF;
    UPDATE public.chi_tiet_chuyen_xe SET trang_thai='DA_DO_HANG',ngay_do_hang=NOW()
    WHERE chuyen_xe_id=p_chuyen_xe_id AND don_hang_id=v_don.id;
    UPDATE public.don_hang SET kho_hien_tai_id=v_nv.kho_hang_id,
      nhan_vien_hien_tai_id=v_nv.id,
      trang_thai=CASE WHEN kho_dich_id=v_nv.kho_hang_id THEN 'DEN_KHO_DICH' ELSE 'DEN_KHO_TRUNG_CHUYEN' END,
      ngay_cap_nhat=NOW() WHERE id=v_don.id;
    v_trang_thai := 'DA_NHAP_KHO';
  ELSE RAISE EXCEPTION 'Thao tác quét không hợp lệ';
  END IF;
  RETURN v_trang_thai;
END;
$$;

GRANT EXECUTE ON FUNCTION public.quan_ly_kho_danh_sach_xe(BIGINT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.quan_ly_kho_danh_sach_kho_den(BIGINT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.quan_ly_kho_danh_sach_chuyen(BIGINT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.quan_ly_kho_gan_xe_tao_chuyen(BIGINT,BIGINT,BIGINT,TIMESTAMPTZ) TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_kho_danh_sach_chuyen() TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_kho_nhap_kien(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.nhan_vien_kho_quet_kien_chuyen(BIGINT,TEXT,TEXT) TO authenticated;
NOTIFY pgrst,'reload schema';

-- BAN SUA TRUY VAN KHO DEN CAP NHAT
-- Sửa riêng danh sách kho đến, không xóa hay thay đổi dữ liệu kho.

CREATE OR REPLACE FUNCTION public.quan_ly_kho_danh_sach_kho_den(p_kho_di_id BIGINT)
RETURNS TABLE(id BIGINT,ma_kho VARCHAR,ten_kho VARCHAR,dia_chi TEXT,
  cap_kho SMALLINT,kho_trung_tam_id BIGINT)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE
  v_kho_quan_ly BIGINT;
  v_cap_quan_ly SMALLINT;
  v_cap_kho_di SMALLINT;
  v_kho_cha BIGINT;
BEGIN
  SELECT nv.kho_hang_id,kh.cap_kho
  INTO v_kho_quan_ly,v_cap_quan_ly
  FROM public.nhan_vien nv
  JOIN public.kho_hang kh ON kh.id=nv.kho_hang_id
  WHERE nv.auth_user_id=auth.uid()
    AND nv.vai_tro='QUAN_LY_KHO'
    AND nv.trang_thai_duyet='DA_DUYET'
    AND nv.trang_thai='HOAT_DONG';

  IF v_kho_quan_ly IS NULL THEN
    RAISE EXCEPTION 'Quản lý chưa được gán kho';
  END IF;

  SELECT kh.cap_kho,kh.kho_trung_tam_id
  INTO v_cap_kho_di,v_kho_cha
  FROM public.kho_hang kh
  WHERE kh.id=p_kho_di_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy kho khởi hành'; END IF;

  IF p_kho_di_id<>v_kho_quan_ly AND NOT (
    v_cap_quan_ly=1 AND v_cap_kho_di=2 AND v_kho_cha=v_kho_quan_ly
  ) THEN
    RAISE EXCEPTION 'Kho khởi hành không thuộc phạm vi quản lý';
  END IF;

  IF v_cap_kho_di=2 THEN
    -- An Phú (cấp 2) sẽ trả đúng Kho trung tâm Sài Gòn (cấp 1).
    RETURN QUERY
    SELECT kh.id,kh.ma_kho::VARCHAR,kh.ten_kho::VARCHAR,kh.dia_chi,
      kh.cap_kho,kh.kho_trung_tam_id
    FROM public.kho_hang kh
    WHERE kh.id=v_kho_cha;
  ELSE
    -- Kho cấp 1 đi xuống kho cấp 2 trực thuộc hoặc sang kho cấp 1 khác.
    RETURN QUERY
    SELECT kh.id,kh.ma_kho::VARCHAR,kh.ten_kho::VARCHAR,kh.dia_chi,
      kh.cap_kho,kh.kho_trung_tam_id
    FROM public.kho_hang kh
    WHERE kh.id<>p_kho_di_id AND kh.trang_thai='HOAT_DONG'
      AND (kh.cap_kho=1 OR (kh.cap_kho=2 AND kh.kho_trung_tam_id=p_kho_di_id))
    ORDER BY kh.cap_kho,kh.ten_kho;
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.quan_ly_kho_danh_sach_kho_den(BIGINT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.quan_ly_kho_danh_sach_kho_den(BIGINT) TO authenticated;
NOTIFY pgrst,'reload schema';

-- BAN VA CAP 2 TAO CHUYEN LEN CAP 1
-- Bản sửa tối giản: kho cấp 2 luôn lấy được kho cấp 1 trực thuộc.
-- Không thay đổi dữ liệu và không bỏ kiểm tra quyền khi tạo chuyến.

CREATE OR REPLACE FUNCTION public.quan_ly_kho_danh_sach_kho_den(p_kho_di_id BIGINT)
RETURNS TABLE(id BIGINT,ma_kho VARCHAR,ten_kho VARCHAR,dia_chi TEXT,
  cap_kho SMALLINT,kho_trung_tam_id BIGINT)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_cap_kho_di SMALLINT; v_kho_cha BIGINT;
BEGIN
  SELECT kh.cap_kho,kh.kho_trung_tam_id
  INTO v_cap_kho_di,v_kho_cha
  FROM public.kho_hang kh WHERE kh.id=p_kho_di_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy kho khởi hành'; END IF;

  IF v_cap_kho_di=2 THEN
    IF v_kho_cha IS NULL THEN
      RAISE EXCEPTION 'Kho cấp 2 chưa được gán kho cấp 1 trực thuộc';
    END IF;
    RETURN QUERY
    SELECT kh.id,kh.ma_kho::VARCHAR,kh.ten_kho::VARCHAR,kh.dia_chi,
      kh.cap_kho,kh.kho_trung_tam_id
    FROM public.kho_hang kh WHERE kh.id=v_kho_cha;
  ELSE
    RETURN QUERY
    SELECT kh.id,kh.ma_kho::VARCHAR,kh.ten_kho::VARCHAR,kh.dia_chi,
      kh.cap_kho,kh.kho_trung_tam_id
    FROM public.kho_hang kh
    WHERE kh.id<>p_kho_di_id AND kh.trang_thai='HOAT_DONG'
      AND (kh.cap_kho=1 OR (kh.cap_kho=2 AND kh.kho_trung_tam_id=p_kho_di_id))
    ORDER BY kh.cap_kho,kh.ten_kho;
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.quan_ly_kho_danh_sach_kho_den(BIGINT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.quan_ly_kho_danh_sach_kho_den(BIGINT) TO authenticated;
NOTIFY pgrst,'reload schema';

-- BAN VA QUAN LY KHO CAP 2 GAN XE
-- Cho quản lý kho cấp 2 gán xe tạo chuyến lên kho cấp 1 trực thuộc.
-- Không xóa dữ liệu.

CREATE OR REPLACE FUNCTION public.quan_ly_kho_danh_sach_xe(p_kho_id BIGINT)
RETURNS TABLE(id BIGINT,bien_so_xe VARCHAR,tai_trong NUMERIC,trang_thai VARCHAR,
  tai_xe_id BIGINT,ten_tai_xe VARCHAR,so_dien_thoai VARCHAR)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_cap SMALLINT; v_kho_cha BIGINT;
BEGIN
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_id) THEN
    RAISE EXCEPTION 'Kho không thuộc phạm vi quản lý';
  END IF;
  SELECT kh.cap_kho,kh.kho_trung_tam_id INTO v_cap,v_kho_cha
  FROM public.kho_hang kh WHERE kh.id=p_kho_id;

  RETURN QUERY
  SELECT x.id,x.bien_so_xe::VARCHAR,x.tai_trong,x.trang_thai::VARCHAR,
    x.tai_xe_id,nv.ho_ten::VARCHAR,nv.so_dien_thoai::VARCHAR
  FROM public.xe x
  JOIN public.nhan_vien nv ON nv.id=x.tai_xe_id
  WHERE (
      nv.kho_hang_id=p_kho_id
      OR (v_cap=2 AND nv.kho_hang_id=v_kho_cha)
    )
    AND nv.vai_tro='VAN_CHUYEN'
    AND nv.trang_thai_duyet='DA_DUYET'
    AND nv.trang_thai='HOAT_DONG'
    AND NOT EXISTS(
      SELECT 1 FROM public.chuyen_xe cx
      WHERE cx.xe_id=x.id
        AND cx.trang_thai IN ('CHO_KHOI_HANH','DANG_XEP_HANG','DANG_DI')
    )
  ORDER BY CASE x.trang_thai WHEN 'SAN_SANG' THEN 0 ELSE 1 END,x.bien_so_xe;
END;
$$;

CREATE OR REPLACE FUNCTION public.quan_ly_kho_gan_xe_tao_chuyen(
  p_kho_di_id BIGINT,p_kho_den_id BIGINT,p_xe_id BIGINT,
  p_ngay_du_kien TIMESTAMPTZ DEFAULT NULL
) RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv_id BIGINT; v_chuyen_id BIGINT; v_ma VARCHAR;
  v_cap_di SMALLINT; v_kho_cha BIGINT;
BEGIN
  IF p_kho_di_id=p_kho_den_id THEN RAISE EXCEPTION 'Kho đi và kho đến phải khác nhau'; END IF;
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_di_id) THEN
    RAISE EXCEPTION 'Bạn không quản lý kho khởi hành';
  END IF;
  SELECT nv.id INTO v_nv_id FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid() AND nv.vai_tro='QUAN_LY_KHO'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF v_nv_id IS NULL THEN RAISE EXCEPTION 'Tài khoản không phải quản lý kho'; END IF;

  SELECT kh.cap_kho,kh.kho_trung_tam_id INTO v_cap_di,v_kho_cha
  FROM public.kho_hang kh WHERE kh.id=p_kho_di_id;
  IF v_cap_di=2 AND p_kho_den_id<>v_kho_cha THEN
    RAISE EXCEPTION 'Kho cấp 2 chỉ được tạo chuyến lên kho cấp 1 trực thuộc';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.quan_ly_kho_danh_sach_kho_den(p_kho_di_id) d
    WHERE d.id=p_kho_den_id
  ) THEN RAISE EXCEPTION 'Kho đến không đúng tuyến được phép'; END IF;

  IF NOT EXISTS(
    SELECT 1 FROM public.xe x
    JOIN public.nhan_vien tx ON tx.id=x.tai_xe_id
    WHERE x.id=p_xe_id AND x.trang_thai='SAN_SANG'
      AND tx.vai_tro='VAN_CHUYEN'
      AND (tx.kho_hang_id=p_kho_di_id OR (v_cap_di=2 AND tx.kho_hang_id=v_kho_cha))
  ) THEN RAISE EXCEPTION 'Xe không sẵn sàng hoặc không thuộc hệ thống kho'; END IF;
  IF EXISTS(SELECT 1 FROM public.chuyen_xe cx WHERE cx.xe_id=p_xe_id
    AND cx.trang_thai IN ('CHO_KHOI_HANH','DANG_XEP_HANG','DANG_DI')) THEN
    RAISE EXCEPTION 'Xe đang có chuyến chưa hoàn thành';
  END IF;

  v_ma := 'CX' || TO_CHAR(NOW(),'YYMMDDHH24MISS') || UPPER(SUBSTR(REPLACE(gen_random_uuid()::TEXT,'-',''),1,5));
  INSERT INTO public.chuyen_xe(xe_id,ma_chuyen,trang_thai,ngay_du_kien)
  VALUES(p_xe_id,v_ma,'CHO_KHOI_HANH',p_ngay_du_kien) RETURNING id INTO v_chuyen_id;
  INSERT INTO public.chuyen_xe_chang(chuyen_xe_id,thu_tu_chuyen,kho_di_id,
    kho_den_id,nguoi_phan_cong_id,ngay_den_du_kien)
  VALUES(v_chuyen_id,1,p_kho_di_id,p_kho_den_id,v_nv_id,p_ngay_du_kien);
  RETURN v_chuyen_id;
END;
$$;

REVOKE ALL ON FUNCTION public.quan_ly_kho_danh_sach_xe(BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.quan_ly_kho_gan_xe_tao_chuyen(BIGINT,BIGINT,BIGINT,TIMESTAMPTZ) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.quan_ly_kho_danh_sach_xe(BIGINT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.quan_ly_kho_gan_xe_tao_chuyen(BIGINT,BIGINT,BIGINT,TIMESTAMPTZ) TO authenticated;
NOTIFY pgrst,'reload schema';

-- BO SUNG DIA BAN KHO CHO MAN HIN TAO KHO CAP 2
-- Bổ sung tỉnh/thành và phường/xã của kho vào dữ liệu tổng quan.
-- Không xóa dữ liệu.

CREATE OR REPLACE FUNCTION public.quan_ly_kho_tong_quan_theo_kho(p_kho_id BIGINT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_kho public.kho_hang%ROWTYPE; v_quan_ly_ten TEXT;
  v_tinh_thanh VARCHAR; v_phuong_xa VARCHAR;
BEGIN
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_id) THEN
    RAISE EXCEPTION 'Kho không thuộc phạm vi quản lý';
  END IF;
  SELECT * INTO v_kho FROM public.kho_hang WHERE id=p_kho_id;
  SELECT nv.ho_ten INTO v_quan_ly_ten FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid();
  SELECT kv.tinh_thanh,kv.phuong_xa INTO v_tinh_thanh,v_phuong_xa
  FROM public.khu_vuc kv WHERE kv.id=v_kho.khu_vuc_id;

  RETURN jsonb_build_object(
    'quan_ly_ten',v_quan_ly_ten,'kho_id',v_kho.id,
    'ma_kho',v_kho.ma_kho,'ten_kho',v_kho.ten_kho,
    'dia_chi',v_kho.dia_chi,'cap_kho',v_kho.cap_kho,
    'tinh_thanh',v_tinh_thanh,'phuong_xa',v_phuong_xa,
    'don_tai_kho',(SELECT COUNT(*) FROM public.don_hang dh WHERE dh.kho_hien_tai_id=v_kho.id),
    'don_cho_xu_ly',(SELECT COUNT(*) FROM public.don_hang dh WHERE
      (dh.kho_gui_id=v_kho.id OR dh.kho_dich_id=v_kho.id OR dh.kho_hien_tai_id=v_kho.id)
      AND dh.trang_thai IN ('DA_LAY_HANG','DEN_KHO_TRUNG_CHUYEN','DEN_KHO_DICH')),
    'dang_van_chuyen',(SELECT COUNT(*) FROM public.don_hang dh WHERE
      (dh.kho_gui_id=v_kho.id OR dh.kho_dich_id=v_kho.id) AND dh.trang_thai='DANG_VAN_CHUYEN'),
    'da_giao',(SELECT COUNT(*) FROM public.don_hang dh WHERE
      (dh.kho_gui_id=v_kho.id OR dh.kho_dich_id=v_kho.id) AND dh.trang_thai='DA_GIAO_HANG')
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.quan_ly_kho_tong_quan_theo_kho(BIGINT) TO authenticated;
NOTIFY pgrst,'reload schema';

-- GIOI HAN QUAN LY CAP 2 CHI XE VA NHAN SU CUA KHO MINH
-- Quản lý kho cấp 2 chỉ xem/gán nhân viên và xe thuộc chính kho cấp 2.
-- Xe của kho cấp 2 vẫn được tạo chuyến lên kho cấp 1 trực thuộc.
-- Không xóa dữ liệu.

CREATE OR REPLACE FUNCTION public.quan_ly_kho_danh_sach_xe(p_kho_id BIGINT)
RETURNS TABLE(id BIGINT,bien_so_xe VARCHAR,tai_trong NUMERIC,trang_thai VARCHAR,
  tai_xe_id BIGINT,ten_tai_xe VARCHAR,so_dien_thoai VARCHAR)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
BEGIN
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_id) THEN
    RAISE EXCEPTION 'Kho không thuộc phạm vi quản lý';
  END IF;
  RETURN QUERY
  SELECT x.id,x.bien_so_xe::VARCHAR,x.tai_trong,x.trang_thai::VARCHAR,
    x.tai_xe_id,nv.ho_ten::VARCHAR,nv.so_dien_thoai::VARCHAR
  FROM public.xe x
  JOIN public.nhan_vien nv ON nv.id=x.tai_xe_id
  WHERE nv.kho_hang_id=p_kho_id
    AND nv.vai_tro='VAN_CHUYEN'
    AND nv.trang_thai_duyet='DA_DUYET'
    AND nv.trang_thai='HOAT_DONG'
    AND NOT EXISTS(
      SELECT 1 FROM public.chuyen_xe cx
      WHERE cx.xe_id=x.id
        AND cx.trang_thai IN ('CHO_KHOI_HANH','DANG_XEP_HANG','DANG_DI')
    )
  ORDER BY CASE x.trang_thai WHEN 'SAN_SANG' THEN 0 ELSE 1 END,x.bien_so_xe;
END;
$$;

CREATE OR REPLACE FUNCTION public.quan_ly_kho_gan_xe_tao_chuyen(
  p_kho_di_id BIGINT,p_kho_den_id BIGINT,p_xe_id BIGINT,
  p_ngay_du_kien TIMESTAMPTZ DEFAULT NULL
) RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_nv_id BIGINT; v_chuyen_id BIGINT; v_ma VARCHAR;
  v_cap_di SMALLINT; v_kho_cha BIGINT;
BEGIN
  IF p_kho_di_id=p_kho_den_id THEN RAISE EXCEPTION 'Kho đi và kho đến phải khác nhau'; END IF;
  IF NOT public.quan_ly_kho_duoc_quan_ly(p_kho_di_id) THEN
    RAISE EXCEPTION 'Bạn không quản lý kho khởi hành';
  END IF;
  SELECT nv.id INTO v_nv_id FROM public.nhan_vien nv
  WHERE nv.auth_user_id=auth.uid() AND nv.vai_tro='QUAN_LY_KHO'
    AND nv.trang_thai_duyet='DA_DUYET' AND nv.trang_thai='HOAT_DONG';
  IF v_nv_id IS NULL THEN RAISE EXCEPTION 'Tài khoản không phải quản lý kho'; END IF;

  SELECT kh.cap_kho,kh.kho_trung_tam_id INTO v_cap_di,v_kho_cha
  FROM public.kho_hang kh WHERE kh.id=p_kho_di_id;
  IF v_cap_di=2 AND p_kho_den_id<>v_kho_cha THEN
    RAISE EXCEPTION 'Kho cấp 2 chỉ được tạo chuyến lên kho cấp 1 trực thuộc';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.quan_ly_kho_danh_sach_kho_den(p_kho_di_id) d
    WHERE d.id=p_kho_den_id
  ) THEN RAISE EXCEPTION 'Kho đến không đúng tuyến được phép'; END IF;

  IF NOT EXISTS(
    SELECT 1 FROM public.xe x
    JOIN public.nhan_vien tx ON tx.id=x.tai_xe_id
    WHERE x.id=p_xe_id AND x.trang_thai='SAN_SANG'
      AND tx.vai_tro='VAN_CHUYEN'
      AND tx.kho_hang_id=p_kho_di_id
      AND tx.trang_thai_duyet='DA_DUYET'
      AND tx.trang_thai='HOAT_DONG'
  ) THEN RAISE EXCEPTION 'Xe không sẵn sàng hoặc không thuộc kho cấp 2 này'; END IF;
  IF EXISTS(SELECT 1 FROM public.chuyen_xe cx WHERE cx.xe_id=p_xe_id
    AND cx.trang_thai IN ('CHO_KHOI_HANH','DANG_XEP_HANG','DANG_DI')) THEN
    RAISE EXCEPTION 'Xe đang có chuyến chưa hoàn thành';
  END IF;

  v_ma := 'CX' || TO_CHAR(NOW(),'YYMMDDHH24MISS') || UPPER(SUBSTR(REPLACE(gen_random_uuid()::TEXT,'-',''),1,5));
  INSERT INTO public.chuyen_xe(xe_id,ma_chuyen,trang_thai,ngay_du_kien)
  VALUES(p_xe_id,v_ma,'CHO_KHOI_HANH',p_ngay_du_kien) RETURNING id INTO v_chuyen_id;
  INSERT INTO public.chuyen_xe_chang(chuyen_xe_id,thu_tu_chuyen,kho_di_id,
    kho_den_id,nguoi_phan_cong_id,ngay_den_du_kien)
  VALUES(v_chuyen_id,1,p_kho_di_id,p_kho_den_id,v_nv_id,p_ngay_du_kien);
  RETURN v_chuyen_id;
END;
$$;

